(function(){"use strict";function normalizeProductTitles(){const titleBlocks=document.querySelectorAll(".Gstore-product-card__title");if(!titleBlocks.length){return}titleBlocks.forEach(titleBlock=>{titleBlock.querySelectorAll("br").forEach(br=>br.remove());const link=titleBlock.querySelector("a");if(!link){return}const normalizedText=link.textContent.replace(/\s+/g," ").trim();link.textContent=normalizedText})}function normalizePriceDetails(){const priceBlocks=document.querySelectorAll(".Gstore-product-card__price-details");if(!priceBlocks.length){return}priceBlocks.forEach(priceBlock=>{priceBlock.querySelectorAll("br").forEach(br=>br.remove());priceBlock.querySelectorAll("p").forEach(paragraph=>{while(paragraph.firstChild){paragraph.parentNode.insertBefore(paragraph.firstChild,paragraph)}paragraph.remove()})})}function initFavoriteButtons(){const hasCore=()=>typeof window.GstoreFavorites?.toggle==="function";const setUI=(button,icon,isActive)=>{button.classList.toggle("is-favorited",isActive);button.setAttribute("aria-pressed",String(isActive));if(icon){icon.classList.toggle("fa-solid",isActive);icon.classList.toggle("fa-regular",!isActive)}};const syncAllButtons=async()=>{if(!hasCore())return;try{await window.GstoreFavorites.ready;const ids=await window.GstoreFavorites.getIds();const set=new Set(ids);document.querySelectorAll(".Gstore-product-card__favorite").forEach(button=>{const card=button.closest(".Gstore-product-card");if(!card)return;const productId=getProductId(card);if(!productId)return;const icon=button.querySelector(".Gstore-product-card__favorite-icon");setUI(button,icon,set.has(String(productId)))})}catch(e){}};document.addEventListener("click",async e=>{const button=e.target?.closest?.(".Gstore-product-card__favorite");if(!button)return;e.preventDefault();e.stopPropagation();if(!hasCore())return;const productCard=button.closest(".Gstore-product-card");if(!productCard)return;const productId=getProductId(productCard);if(!productId)return;const icon=button.querySelector(".Gstore-product-card__favorite-icon");const prev=button.classList.contains("is-favorited");setUI(button,icon,!prev);try{const result=await window.GstoreFavorites.toggle(productId);setUI(button,icon,Boolean(result?.isFavorited))}catch(err){setUI(button,icon,prev)}});syncAllButtons();window.addEventListener("gstore:favorites-changed",()=>{syncAllButtons()})}function getProductId(productCard){const classes=productCard.className.split(" ");for(let className of classes){if(className.startsWith("post-")){return className.replace("post-","")}}return null}const gstoreInstallmentCache=new Map;const gstoreInstallmentQuotesCache=new Map;const gstoreInstallmentInFlight=new Map;function resolveInstallmentAjaxUrl(){if(typeof gstoreProductCardConfig!=="undefined"&&gstoreProductCardConfig?.ajaxUrl){return String(gstoreProductCardConfig.ajaxUrl)}if(typeof gstoreFavoritesConfig!=="undefined"&&gstoreFavoritesConfig?.ajaxUrl){return String(gstoreFavoritesConfig.ajaxUrl)}if(typeof gstoreSingleProductInstallments!=="undefined"&&gstoreSingleProductInstallments?.ajaxUrl){return String(gstoreSingleProductInstallments.ajaxUrl)}if(typeof gstoreSettings!=="undefined"&&gstoreSettings?.ajax_url){return String(gstoreSettings.ajax_url)}if(typeof ajaxurl!=="undefined"&&ajaxurl){return String(ajaxurl)}var base=document.querySelector('link[rel="https://api.w.org/"]');if(base){try{var restUrl=new URL(base.getAttribute("href"));return restUrl.origin+restUrl.pathname.replace(/wp-json\/?.*$/,"wp-admin/admin-ajax.php")}catch(e){}}return"/wp-admin/admin-ajax.php"}function resolveInstallmentAction(){if(typeof gstoreProductCardConfig!=="undefined"&&gstoreProductCardConfig?.action){return String(gstoreProductCardConfig.action)}if(typeof gstoreSingleProductInstallments!=="undefined"&&gstoreSingleProductInstallments?.action){return String(gstoreSingleProductInstallments.action)}return"gstore_blu_get_product_installment_quotes"}function formatCurrency(value){if(!Number.isFinite(value))return"";try{return new Intl.NumberFormat("pt-BR",{style:"currency",currency:"BRL"}).format(value)}catch(err){return"R$ "+value.toFixed(2).replace(".",",")}}function chooseQuote(quotes,preferred){if(!quotes||typeof quotes!=="object")return null;if(quotes[preferred])return quotes[preferred];const keys=Object.keys(quotes).map(key=>parseInt(key,10)).filter(key=>Number.isFinite(key)).sort((a,b)=>b-a);if(!keys.length)return null;return quotes[String(keys[0])]||null}function initProductCardInstallmentQuotes(){const targets=Array.from(document.querySelectorAll('[data-gstore-installment-scope="card"]'));if(!targets.length){return}function getMaxInstallments(target){const raw=target?.dataset?.maxInstallments||typeof gstoreSingleProductInstallments!=="undefined"&&gstoreSingleProductInstallments?.max||"21";const parsed=parseInt(String(raw),10);return Number.isFinite(parsed)&&parsed>0?parsed:21}function applyFallback(target){const fallback=String(target?.dataset?.initialText||"").trim();if(fallback){target.textContent=fallback;target.hidden=false}else{target.hidden=true}}function applyText(target,text){target.textContent=text;target.hidden=!text}function requestTargetQuotes(target){const productId=String(target?.dataset?.productId||"");if(!productId){applyFallback(target);return}const quantity=1;const max=getMaxInstallments(target);const signature=productId+"|"+quantity+"|"+max;if(gstoreInstallmentQuotesCache.has(signature)){const cachedQuotes=gstoreInstallmentQuotesCache.get(signature);if(cachedQuotes&&typeof cachedQuotes==="object"){const quoteKeys=Object.keys(cachedQuotes).map(key=>parseInt(key,10)).filter(key=>Number.isFinite(key)).sort((a,b)=>b-a);if(quoteKeys.length>0){const maxAvailable=quoteKeys[0];const preferred=chooseQuote(cachedQuotes,String(maxAvailable));if(preferred&&preferred.installments&&preferred.per_installment_text){const maxText="ou "+preferred.installments+"x de "+preferred.per_installment_text;applyText(target,maxText);return}}}}if(gstoreInstallmentInFlight.has(signature)){return}const ajaxUrl=target?.dataset?.ajaxUrl||resolveInstallmentAjaxUrl();const action=resolveInstallmentAction();if(!ajaxUrl){applyFallback(target);return}const body=new URLSearchParams;body.set("action",action);body.set("product_id",productId);body.set("quantity",String(quantity));body.set("max",String(max));body.set("only_installments",String(max));body.set("gstore_price_context","card");const fetchPromise=fetch(ajaxUrl,{method:"POST",headers:{"Content-Type":"application/x-www-form-urlencoded; charset=UTF-8"},credentials:"same-origin",body:body.toString()}).then(async response=>{let payload;try{payload=await response.json()}catch(parseError){throw new Error("Resposta inválida do servidor (JSON parse error).")}if(!response.ok||!payload?.success){throw new Error(payload?.data?.message||"Falha ao obter parcelas.")}if(!payload?.data||typeof payload.data!=="object"){throw new Error("Dados de resposta inválidos.")}if(!payload.data.quotes||typeof payload.data.quotes!=="object"){throw new Error("Quotes não encontrados na resposta.")}const quoteKeys=Object.keys(payload.data.quotes).map(key=>parseInt(key,10)).filter(key=>Number.isFinite(key)).sort((a,b)=>b-a);const preferredMax=quoteKeys.length>0?quoteKeys[0]:payload.data.max||max||21;const quote=chooseQuote(payload.data.quotes,String(preferredMax));if(!quote||!quote.installments||!quote.per_installment_text){throw new Error("Parcelas indisponíveis.")}const text="ou "+quote.installments+"x de "+quote.per_installment_text;const cacheSignature=productId+"|"+quantity+"|"+quote.installments;gstoreInstallmentCache.set(cacheSignature,text);gstoreInstallmentQuotesCache.set(cacheSignature,payload.data.quotes);applyText(target,text)}).catch(function(){applyFallback(target)}).finally(function(){gstoreInstallmentInFlight.delete(signature)});gstoreInstallmentInFlight.set(signature,fetchPromise)}if("IntersectionObserver"in window){const observer=new IntersectionObserver(function(entries){entries.forEach(function(entry){if(!entry.isIntersecting)return;const target=entry.target;observer.unobserve(target);requestTargetQuotes(target)})},{rootMargin:"120px 0px"});targets.forEach(function(target){observer.observe(target)})}else{targets.forEach(function(target){requestTargetQuotes(target)})}}function initProductCards(){initFavoriteButtons();normalizeProductTitles();normalizePriceDetails();initProductCardInstallmentQuotes()}if(document.readyState==="loading"){document.addEventListener("DOMContentLoaded",initProductCards)}else{initProductCards()}})();
